package it.darkroom.timer.assistant.equipment;

import android.app.Activity;
import android.content.Intent;
import android.os.Bundle;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.Toast;

import org.json.JSONObject;

import java.util.List;
import java.util.Locale;

import it.darkroom.timer.assistant.data.AssistantDatabase;
import it.darkroom.timer.assistant.search.SmartCatalog;
import it.darkroom.timer.assistant.search.SmartSearchActivity;
import it.darkroom.timer.assistant.ui.AssistantUi;

/** Modern R6 equipment UX. Catalog search is primary; manual technical entry is fallback only. */
public final class MyEquipmentActivity extends Activity {
    private static final int PICK_TANK=6210,PICK_EQUIPMENT=6211;
    private AssistantDatabase db;private LinearLayout host,list;
    @Override protected void onCreate(Bundle b){super.onCreate(b);db=new AssistantDatabase(this);build();}
    @Override protected void onResume(){super.onResume();refresh();}
    @Override protected void onDestroy(){if(db!=null)db.close();super.onDestroy();}

    private void build(){LinearLayout root=AssistantUi.screen(this,"DARKROOM ASSISTANT · ATTREZZATURA","LA MIA ATTREZZATURA","Catalogo tecnico separato da ciò che possiedi realmente.");Button add=AssistantUi.primaryButton(this,"AGGIUNGI TANK");add.setOnClickListener(v->searchTank());root.addView(add,AssistantUi.margin(this,-1,AssistantUi.dp(this,58),0,0,0,8));Button browse=AssistantUi.secondaryButton(this,"CERCA ATTREZZATURA / PROCESSORI");browse.setOnClickListener(v->searchEquipment());root.addView(browse,AssistantUi.margin(this,-1,AssistantUi.dp(this,52),0,0,0,12));host=new LinearLayout(this);host.setOrientation(LinearLayout.VERTICAL);root.addView(host);root.addView(AssistantUi.section(this,"LE MIE TANK"));list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);Button back=AssistantUi.secondaryButton(this,"← ASSISTANT");back.setOnClickListener(v->finish());root.addView(back,AssistantUi.margin(this,-1,AssistantUi.dp(this,50),0,14,0,0));refresh();}
    private void searchTank(){Intent i=searchIntent("CERCA TANK","Cerca marca o modello...","TANK",true);startActivityForResult(i,PICK_TANK);}
    private void searchEquipment(){Intent i=searchIntent("CERCA ATTREZZATURA","Cerca tank, processore o attrezzatura...","TANK,PROCESSOR,EQUIPMENT",false);startActivityForResult(i,PICK_EQUIPMENT);}
    private Intent searchIntent(String title,String hint,String categories,boolean manual){Intent i=new Intent(this,SmartSearchActivity.class);i.putExtra(SmartSearchActivity.EXTRA_TITLE,title);i.putExtra(SmartSearchActivity.EXTRA_HINT,hint);i.putExtra(SmartSearchActivity.EXTRA_CATEGORIES,categories);i.putExtra(SmartSearchActivity.EXTRA_ALLOW_MANUAL,manual);return i;}

    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;if(req==PICK_TANK){if(data.getBooleanExtra(SmartSearchActivity.RESULT_MANUAL,false)){manualForm();return;}String raw=data.getStringExtra(SmartSearchActivity.RESULT_RECORD);if(raw!=null)try{catalogTankForm(new JSONObject(raw));}catch(Exception e){toast("Tank catalogo non leggibile");}}else if(req==PICK_EQUIPMENT){String raw=data.getStringExtra(SmartSearchActivity.RESULT_RECORD);if(raw!=null)try{showTechnical(new JSONObject(raw));}catch(Exception ignored){}}}

    private void catalogTankForm(JSONObject r){host.removeAllViews();JSONObject t=SmartCatalog.technical(r);LinearLayout c=AssistantUi.card(this);c.addView(AssistantUi.cardTitle(this,r.optString("name","Tank")));String capacity="35 mm: "+known(t,"capacity35")+" · 120: "+known(t,"capacity120");String rotation=t.has("minRotationMl")?t.optString("minRotationMl")+" ml":"NON DOCUMENTATO";c.addView(AssistantUi.secondary(this,r.optString("manufacturer","")+" · "+t.optString("system","Sistema non documentato")+"\n"+capacity+"\nRotazione: "+rotation+"\n"+SmartCatalog.sourceDetail(r)));host.addView(c);host.addView(AssistantUi.section(this,"DATI PERSONALI"));EditText personal=AssistantUi.field(this,"Nome personale · opzionale");EditText qty=AssistantUi.numberField(this,"Quantità posseduta");qty.setText("1");EditText notes=AssistantUi.field(this,"Note personali · opzionale");for(EditText e:new EditText[]{personal,qty,notes})host.addView(e,AssistantUi.margin(this,-1,AssistantUi.dp(this,52),0,0,0,7));Button save=AssistantUi.primaryButton(this,"AGGIUNGI TANK");save.setOnClickListener(v->{int n=parseInt(qty.getText().toString(),-1);if(n<=0){toast("Inserisci una quantità positiva");return;}AssistantDatabase.TankItem x=new AssistantDatabase.TankItem();x.sourceType=AssistantDatabase.SOURCE_CATALOG;x.sourceModelKey=r.optString("id","");x.manufacturer=r.optString("manufacturer","");String full=r.optString("name","");x.model=full.startsWith(x.manufacturer+" ")?full.substring(x.manufacturer.length()+1):full;x.personalName=personal.getText().toString().trim();x.quantityOwned=n;x.notes=notes.getText().toString().trim();x.system=t.optString("system","NON DOCUMENTATO");x.tankType=t.optString("tankType","NON DOCUMENTATO");x.capacity35=t.has("capacity35")?t.optInt("capacity35",0):0;x.capacity120=t.has("capacity120")?t.optInt("capacity120",0):0;x.minInversionMl=t.has("minInversionMl")?t.optDouble("minInversionMl",0):0;x.minRotationMl=t.has("minRotationMl")?t.optDouble("minRotationMl",0):0;x.maxVolumeMl=t.has("maxVolumeMl")?t.optDouble("maxVolumeMl",0):0;x.cpe2Compatible=t.optBoolean("cpe2Compatible",false);x.liftCompatible=t.optBoolean("liftCompatible",false);x.technicalSource=SmartCatalog.sourceDetail(r);x.dataType=t.optString("dataType","DATI TECNICI / FONTE");db.saveTank(x);host.removeAllViews();refresh();toast("Tank aggiunta");});host.addView(save,AssistantUi.margin(this,-1,AssistantUi.dp(this,56),0,8,0,10));Button cancel=AssistantUi.ghostButton(this,"ANNULLA");cancel.setOnClickListener(v->host.removeAllViews());host.addView(cancel,AssistantUi.margin(this,-1,AssistantUi.dp(this,48),0,0,0,10));}

    private void manualForm(){host.removeAllViews();host.addView(AssistantUi.emptyState(this,"TANK NON TROVATA","Inserimento manuale: i valori saranno marcati come dati personali, non come fonte ufficiale."));EditText maker=AssistantUi.field(this,"Produttore");EditText model=AssistantUi.field(this,"Modello");EditText personal=AssistantUi.field(this,"Nome personale · opzionale");EditText c35=AssistantUi.numberField(this,"Capacità 35 mm · lascia vuoto se ignota");EditText c120=AssistantUi.numberField(this,"Capacità 120 · lascia vuoto se ignota");EditText rot=AssistantUi.numberField(this,"Minimo rotazione ml · lascia vuoto se ignoto");EditText notes=AssistantUi.field(this,"Note / compatibilità dichiarate");for(EditText e:new EditText[]{maker,model,personal,c35,c120,rot,notes})host.addView(e,AssistantUi.margin(this,-1,AssistantUi.dp(this,52),0,7,0,0));Button save=AssistantUi.primaryButton(this,"SALVA TANK PERSONALE");save.setOnClickListener(v->{if(model.getText().toString().trim().isEmpty()){toast("Inserisci il modello");return;}AssistantDatabase.TankItem x=new AssistantDatabase.TankItem();x.sourceType=AssistantDatabase.SOURCE_USER;x.manufacturer=maker.getText().toString().trim();x.model=model.getText().toString().trim();x.personalName=personal.getText().toString().trim();x.capacity35=parseOptionalInt(c35.getText().toString());x.capacity120=parseOptionalInt(c120.getText().toString());x.minRotationMl=parseOptionalDouble(rot.getText().toString());x.notes=notes.getText().toString().trim();x.system="NON DOCUMENTATO";x.tankType="PERSONALE";x.cpe2Compatible=x.notes.toLowerCase(Locale.ITALY).contains("cpe2 compatibile");x.liftCompatible=x.notes.toLowerCase(Locale.ITALY).contains("lift compatibile");x.technicalSource="Utente";x.dataType="DATO PERSONALE";db.saveTank(x);host.removeAllViews();refresh();toast("Tank personale salvata");});host.addView(save,AssistantUi.margin(this,-1,AssistantUi.dp(this,56),0,10,0,10));}

    private void refresh(){if(list==null)return;list.removeAllViews();List<AssistantDatabase.TankItem> tanks=db.listTanks();if(tanks.isEmpty()){list.addView(AssistantUi.emptyState(this,"NESSUNA TANK CONFIGURATA","Tocca AGGIUNGI TANK e prova “2520” o “jobo”. Il volume manuale resta sempre disponibile in Nuovo sviluppo."));return;}for(AssistantDatabase.TankItem t:tanks){String origin=AssistantDatabase.SOURCE_CATALOG.equals(t.sourceType)?"CATALOGO VERIFICATO":"DATO PERSONALE";Button row=AssistantUi.resultRow(this,t.displayName(),"35 mm "+knownInt(t.capacity35)+" · 120 "+knownInt(t.capacity120),origin);row.setOnClickListener(v->detail(t.id));list.addView(row,AssistantUi.margin(this,-1,AssistantUi.dp(this,76),0,0,0,7));}}
    private void detail(long id){AssistantDatabase.TankItem t=db.getTank(id);if(t==null)return;host.removeAllViews();LinearLayout c=AssistantUi.card(this);c.addView(AssistantUi.cardTitle(this,t.displayName()));String cpe=t.cpe2Compatible?"CONFERMATA":"NON DOCUMENTATA / NON CONFERMATA";String lift=t.liftCompatible?"CONFERMATA":"NON DOCUMENTATA / NON CONFERMATA";c.addView(AssistantUi.body(this,"Sistema: "+empty(t.system)+"\nTipo: "+empty(t.tankType)+"\n35 mm: "+knownInt(t.capacity35)+" · 120: "+knownInt(t.capacity120)+"\nMinimo rotazione: "+knownMl(t.minRotationMl)+"\nMinimo inversione: "+knownMl(t.minInversionMl)+"\nCompatibilità CPE2: "+cpe+"\nCompatibilità lift: "+lift));c.addView(AssistantUi.secondary(this,"\nFONTE / PROVENIENZA\n"+empty(t.technicalSource)+"\n"+empty(t.dataType)+"\n\nNOTE PERSONALI\n"+empty(t.notes)));host.addView(c,AssistantUi.margin(this,-1,-2,0,0,0,10));}
    private void showTechnical(JSONObject r){host.removeAllViews();LinearLayout c=AssistantUi.card(this);c.addView(AssistantUi.cardTitle(this,r.optString("name","Attrezzatura")));c.addView(AssistantUi.body(this,r.optString("manufacturer","")+" · "+r.optString("subtitle","")+"\n\n"+SmartCatalog.sourceDetail(r)));host.addView(c,AssistantUi.margin(this,-1,-2,0,0,0,10));}

    private static String known(JSONObject t,String k){return t.has(k)?Integer.toString(t.optInt(k)):"NON DOCUMENTATA";}private static String knownInt(int v){return v>0?Integer.toString(v):(v==0?"NON DOCUMENTATA":"NON DOCUMENTATA");}private static String knownMl(double v){return v>0?String.format(Locale.ITALY,"%.0f ml",v):"NON DOCUMENTATO";}private static String empty(String s){return s==null||s.trim().isEmpty()?"—":s;}private static int parseInt(String s,int d){try{return Integer.parseInt(s.trim());}catch(Exception e){return d;}}private static int parseOptionalInt(String s){return s==null||s.trim().isEmpty()?0:Math.max(0,parseInt(s,0));}private static double parseOptionalDouble(String s){try{return s==null||s.trim().isEmpty()?0:Math.max(0,Double.parseDouble(s.trim().replace(',','.')));}catch(Exception e){return 0;}}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
